    const { port } = server.address();
    server.close((error) => (error ? reject(error) : resolve(port)));
  });
});

const waitFor = async (check, label, timeoutMs = 12_000) => {
  const deadline = Date.now() + timeoutMs;
  let lastError;

  while (Date.now() < deadline) {
    try {
      return await check();
    } catch (error) {
      lastError = error;
      await new Promise((resolve) => setTimeout(resolve, 200));
    }
  }

  throw new Error(`Timed out waiting for ${label}: ${lastError?.message ?? 'unknown error'}`);
};

const request = async (url, options = {}) => {
  const response = await fetch(url, options);
  const text = await response.text();
  let body;

  try {
    body = text ? JSON.parse(text) : null;
  } catch {
    fail(`${options.method ?? 'GET'} ${url} returned non-JSON: ${text}`);
  }

  return { status: response.status, body };
};

const startNode = async (script, env) => {
  const child = spawn(process.execPath, [script], {
    cwd: homework,
    env: { ...process.env, ...env },
    stdio: ['ignore', 'pipe', 'pipe'],
  });
  let output = '';
  child.stdout.on('data', (chunk) => { output += chunk; });
  child.stderr.on('data', (chunk) => { output += chunk; });

  const stop = async () => {
    if (child.exitCode !== null || child.signalCode !== null) return;
    child.kill('SIGTERM');
    await new Promise((resolve) => child.once('exit', resolve));
  };

  child.once('error', (error) => { output += `\n${error.message}`; });
  return { child, output: () => output, stop };
};

