      farmResponse: { farmId: 'farm-b', count: 1 },
    });
  } finally {
    await gateway.stop();
    await mock.stop();
  }
};

const submitViaGateway = async (baseUrl, farmId, value) => request(`${baseUrl}/submit-reading`, {
  method: 'POST',
  headers: { 'Content-Type': 'application/json' },
  body: JSON.stringify({ farmId, metric: 'growthRateCm', value }),
});

const runFinal = async () => {
  log('checking full network, fixed routes, canary routing, and summary');
  const context = await createComposeContext({ includeGateway: true, canaryPercent: 20 });

  try {
    await context.compose(['up', '--detach', '--build']);
    const gatewayUrl = `http://127.0.0.1:${context.ports.gateway}`;
    const farmUrls = {
      a: `http://127.0.0.1:${context.ports.farmA}`,
      b: `http://127.0.0.1:${context.ports.farmB}`,
      c: `http://127.0.0.1:${context.ports.farmC}`,
      av2: `http://127.0.0.1:${context.ports.farmAV2}`,
    };
    await waitFor(() => request(`${gatewayUrl}/submit-reading`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ farmId: 'farm-b', metric: 'growthRateCm', value: 3.1 }),
    }), 'complete routed system', 20_000);

    const unknown = await submitViaGateway(gatewayUrl, 'farm-x', 1);
    assert.equal(unknown.status, 404);
    assert.deepEqual(unknown.body, { error: 'unknown farmId: farm-x' });

    for (const farmId of ['farm-b', 'farm-c']) {
      for (const value of [2, 3, 4]) {
        const response = await submitViaGateway(gatewayUrl, farmId, value);
        assert.equal(response.status, 200);
        assert.equal(response.body.receivedBy, 'buoy-gateway');
        assert.equal(response.body.routedTo, farmId, `${farmId} must have a fixed route`);
        assert.equal(response.body.farmResponse.farmId, farmId);
      }
    }

    let canaryCount = 0;
    for (const _ of Array.from({ length: 100 })) {
      const response = await submitViaGateway(gatewayUrl, 'farm-a', 2);
      assert.equal(response.status, 200);
      assert.ok(['farm-a', 'farm-a-v2'].includes(response.body.routedTo));
      if (response.body.routedTo === 'farm-a-v2') canaryCount += 1;
    }
    assert.ok(canaryCount >= 10 && canaryCount <= 30, `expected 10-30 canary routes, got ${canaryCount}`);

    const [farmA, farmB, farmC, farmAV2] = await Promise.all([
      request(`${farmUrls.a}/status`), request(`${farmUrls.b}/status`), request(`${farmUrls.c}/status`), request(`${farmUrls.av2}/status`),
    ]);
    assert.equal(farmA.body.readings.length + farmAV2.body.readings.length, 100);
    assert.equal(farmB.body.readings.length, 4, 'one readiness request plus three fixed-route requests');
    assert.equal(farmC.body.readings.length, 3);

    const summary = await waitFor(async () => {
      const result = await readRegionalSummary(context.compose);
      assert.equal(result.farms?.['farm-a']?.count, 100);
      assert.equal(result.farms?.['farm-b']?.count, 4);
      assert.equal(result.farms?.['farm-c']?.count, 3);
      return result;
    }, 'final regional summary', 20_000);
    assert.equal(summary.regionalAvgValue, 225.4 / 107);
  } finally {
    await context.cleanup();
  }
};

const showHelp = () => {
  console.log('Usage: node .validation/hw02/run.mjs <step>');
  console.log(`Steps: ${steps.join(', ')}`);
};

const main = async () => {
  if (requestedStep === 'help' || requestedStep === '--help' || requestedStep === '-h') {
    showHelp();
    return;
  }
  if (!steps.includes(requestedStep)) fail(`Unknown step: ${requestedStep}`);

  const runners = {
    setup: runSetup,
    farm: runFarm,
    image: runImage,
    compose: runCompose,
    sidecar: runSidecar,
    gateway: runGateway,
    final: runFinal,
  };
  await runners[requestedStep]();
  console.log(`\n[validation] ${requestedStep} passed`);
};

main().catch((error) => {
  console.error(`\n[validation] ${requestedStep} failed: ${error.message}`);
  process.exitCode = 1;
});

// END AI DISCLOSURE: AI-assisted file. See ai/chats/homework-2-validation.jsonl.

