import { mkdir, readFile, writeFile } from 'node:fs/promises';
import { join } from 'node:path';

const dataRoot = process.env.DATA_ROOT;
const farmIds = (process.env.FARM_IDS || '')
  .split(',')
  .map((farmId) => farmId.trim())
  .filter(Boolean);
const syncIntervalMs = Number(process.env.SYNC_INTERVAL_MS || 5000);

if (!dataRoot) {
  throw new Error('DATA_ROOT is required');
}

if (farmIds.length === 0) {
  throw new Error('FARM_IDS is required');
}

const readFarmReadings = async (farmId) => {
  const readingsPath = join(dataRoot, farmId, 'readings.json');

  try {
    const contents = await readFile(readingsPath, 'utf8');
    return JSON.parse(contents);
  } catch (error) {
    if (error.code === 'ENOENT') {
      return [];
    }

    throw error;
  }
};

const average = (readings) => {
  if (readings.length === 0) {
    return 0;
  }

  const total = readings.reduce(
    (sum, reading) => sum + reading.value,
    0
  );

  return total / readings.length;
};

const syncRegionalSummary = async () => {
  const readingsByFarm = await Promise.all(
    farmIds.map(async (farmId) => ({
      farmId,
      readings: await readFarmReadings(farmId)
    }))
  );

  const farms = Object.fromEntries(
    readingsByFarm.map(({ farmId, readings }) => [
      farmId,
      {
        count: readings.length,
        avgValue: average(readings)
      }
    ])
  );

  const allReadings = readingsByFarm.flatMap(
    ({ readings }) => readings
  );

  const summary = {
    generatedAt: new Date().toISOString(),
    farms,
    regionalAvgValue: average(allReadings)
  };

  await mkdir(dataRoot, { recursive: true });
  await writeFile(
    join(dataRoot, 'regional-summary.json'),
    JSON.stringify(summary, null, 2)
  );
};

const runSync = async () => {
  try {
    await syncRegionalSummary();
    console.log(JSON.stringify({
      event: 'regional_summary_written',
      dataRoot,
      farmIds
    }));
  } catch (error) {
    console.error(JSON.stringify({
      event: 'regional_sync_failed',
      message: error.message
    }));
  }
};

await runSync();
setInterval(runSync, syncIntervalMs);
