import express from 'express';

const app = express();

app.use(express.json());

const port = Number(process.env.PORT || 4000);
const ambassadorUrl = process.env.AMBASSADOR_URL;

if (!ambassadorUrl) {
  throw new Error('AMBASSADOR_URL is required');
}

app.post('/submit-reading', async (request, response) => {
  try {
    const ambassadorResponse = await fetch(`${ambassadorUrl}/reading`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json'
      },
      body: JSON.stringify(request.body)
    });

    const farmResult = await ambassadorResponse.json();

    if (!ambassadorResponse.ok) {
      return response.status(ambassadorResponse.status).json(farmResult);
    }

    return response.json({
      receivedBy: 'buoy-gateway',
      routedTo: farmResult.routedTo,
      farmResponse: farmResult.farmResponse
    });
  } catch (error) {
    return response.status(502).json({
      error: 'failed to reach ambassador'
    });
  }
});

app.listen(port, () => {
