});
import express from 'express';

const app = express();

app.use(express.json());

const port = Number(process.env.PORT || 5000);
const canaryPercent = Number(process.env.CANARY_PERCENT || 20);

const farmUrls = {
  'farm-a': process.env.FARM_A_URL,
  'farm-a-v2': process.env.FARM_A_V2_URL,
  'farm-b': process.env.FARM_B_URL,
  'farm-c': process.env.FARM_C_URL
};

if (!Number.isFinite(canaryPercent) || canaryPercent < 0 || canaryPercent > 100) {
  throw new Error('CANARY_PERCENT must be between 0 and 100');
}

if (Object.values(farmUrls).some((farmUrl) => !farmUrl)) {
  throw new Error('all farm URLs are required');
}

const selectFarm = (farmId) => {
  if (farmId === 'farm-b' || farmId === 'farm-c') {
    return farmId;
  }

  if (farmId === 'farm-a') {
    return Math.random() < canaryPercent / 100
      ? 'farm-a-v2'
      : 'farm-a';
  }

  return null;
};

app.post('/reading', async (request, response) => {
  const { farmId } = request.body || {};
  const routedTo = selectFarm(farmId);

  if (!routedTo) {
    return response.status(404).json({
      error: `unknown farmId: ${farmId}`
    });
  }

  try {
    const farmResult = await fetch(`${farmUrls[routedTo]}/reading`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json'
      },
      body: JSON.stringify(request.body)
    });

    const farmResponse = await farmResult.json();

    if (!farmResult.ok) {
      return response.status(farmResult.status).json(farmResponse);
    }

    return response.json({
      routedTo,
      farmResponse
    });
  } catch (error) {
    return response.status(502).json({
      error: `failed to reach ${routedTo}`
    });
  }
});

app.listen(port, () => {
  console.log(`Ambassador listening on port ${port}`);
});
